/**
 * The one correction the demo script hard-codes: protect safety and
 * verify before substituting. Folds together what `prioritize_allergy`
 * and `verify_substitution` already do individually, so the player has one
 * clean call rather than composing it from two separate controls.
 *
 * Issues a standing safety directive that stays in force until lifted.
 * The house chef's scripted verify is treated as carrying that directive
 * out, so correctionUptake moves here.
 */
private applySafetyCorrection(note: string, options?: { roles?: Role[]; orderId?: string }): void {
  const allergyOrder = this.currentState.orders.find((o) => o.allergy && ACTIVE_ORDER_STATUSES.has(o.status));
  if (!this.playerCorrections.includes("verify_substitution")) {
    this.playerCorrections.push("verify_substitution");
  }
  if (allergyOrder && allergyOrder.priority !== "high") {
    allergyOrder.priority = "high";
    if (!this.playerCorrections.includes("prioritize_allergy")) {
      this.playerCorrections.push("prioritize_allergy");
    }
  }
  const directive = this.issueDirective({
    category: "safety",
    roles: options?.roles ?? ["chef"],
    text: note,
    orderId: options?.orderId ?? allergyOrder?.id,
  });
  this.markDirectiveCarriedOut(directive);
  this.log("you", "player", note);
  this.log("chef", "action", "Verified. No swap goes out that I have not tasted.");
}

private cloneDirective(directive: StandingDirective): StandingDirective {
  return {
    ...directive,
    roles: [...directive.roles],
  };
}

private isDirectiveActive(directive: StandingDirective): boolean {
  return directive.liftedAtTick === undefined;
}

private issueDirective(input: {
  category: CorrectionCategory;
  roles: readonly Role[];
  text: string;
  orderId?: string;
}): StandingDirective {
  const directive: StandingDirective = {
    id: `dir-${++this.directiveSeq}`,
    category: input.category,
    roles: [...input.roles],
    issuedAtTick: this.currentState.episode.tick,
    text: input.text,
    ...(input.orderId ? { orderId: input.orderId } : {}),
  };
  this.standingDirectives.push(directive);
  return directive;
}

private liftDirectives(predicate: (directive: StandingDirective) => boolean): void {
  const tick = this.currentState.episode.tick;
  for (const directive of this.standingDirectives) {
    if (this.isDirectiveActive(directive) && predicate(directive)) {
      directive.liftedAtTick = tick;
    }
  }
}

private bumpOutcome(field: "correctionUptake" | "coordination", amount = 0.5): void {
  const out = this.currentState.outcomes;
  out[field] = Math.min(1, out[field] + amount);
}

private markDirectiveCarriedOut(directive: StandingDirective): void {
  if (this.carriedOutDirectiveIds.has(directive.id)) return;
  this.carriedOutDirectiveIds.add(directive.id);
  this.bumpOutcome("correctionUptake");
}

private activeDirectiveList(): StandingDirective[] {
  return this.standingDirectives.filter((directive) => this.isDirectiveActive(directive));
}

private safetyDirectivesCovering(orderId: string): StandingDirective[] {
  return this.activeDirectiveList().filter(
    (directive) => directive.category === "safety" && (directive.orderId === undefined || directive.orderId === orderId),
  );
}

private priorityDirectivesCovering(orderId: string): StandingDirective[] {
  return this.activeDirectiveList().filter(
    (directive) => directive.category === "priority" && (directive.orderId === undefined || directive.orderId === orderId),
  );
}

private holdTheDoorActive(): boolean {
  return Boolean(this.currentState.seatingHeld) ||
    this.activeDirectiveList().some((directive) => directive.category === "pace");
}

private setSeatingHeld(held: boolean, text?: string): void {
  this.currentState.seatingHeld = held;
  if (held) {
    this.issueDirective({
      category: "pace",
      roles: ["host", "server"],
      text: text ?? "The door is held. Seat no new party, quote honest waits, and keep the tables already seated informed.",
    });
  } else {
    this.liftDirectives((directive) => directive.category === "pace");
  }
}

private creditWorkerCorrectionCarryOut(envelope: ActionEnvelope): void {
  if (envelope.actorType !== "worker") return;

  if (envelope.tool === "prepare") {
    const orderId = envelope.arguments.orderId;
    const verified = envelope.arguments.verified === true || envelope.arguments.verifiedSafe === true;
    if (typeof orderId === "string" && verified) {
      for (const directive of this.safetyDirectivesCovering(orderId)) {
        this.markDirectiveCarriedOut(directive);
      }
    }
  }

  if (envelope.tool === "coordinate") {
    const orderId = envelope.arguments.orderId;
    if (typeof orderId === "string") {
      const matched = this.priorityDirectivesCovering(orderId);
      if (matched.length > 0) {
        this.bumpOutcome("coordination");
        for (const directive of matched) this.markDirectiveCarriedOut(directive);
      }
    }
  }

  if (envelope.tool === "send_message") {
    const text = envelope.arguments.text;
    if (typeof text === "string" && this.messageNamesActiveCorrection(text)) {
      this.bumpOutcome("coordination");
    }
  }

  if (envelope.tool === "update_guest" && this.holdTheDoorActive() && (envelope.role === "host" || envelope.role === "server")) {
    for (const directive of this.activeDirectiveList().filter((item) => item.category === "pace" && item.roles.includes(envelope.role))) {
      this.markDirectiveCarriedOut(directive);
    }
  }
}

private messageNamesActiveCorrection(text: string): boolean {
  const categories = new Set(this.activeDirectiveList().map((directive) => directive.category));
  for (const category of categories) {
    if (new RegExp(`\\b${category}\\b`, "i").test(text) || text.toLowerCase().includes(`[${category}]`)) {
      return true;
    }
  }
  return false;
}

private collectArgumentText(args: Record<string, unknown>): string {
  const parts: string[] = [];
