private isCorrectionCategory(value: unknown): value is CorrectionCategory {
  return value === "safety" || value === "priority" || value === "quality" || value === "pace";
}

private parseDirectiveRoles(value: unknown, fallback: Role): Role[] {
  const allowed = new Set<Role>(["host", "supply_lead", "chef", "server"]);
  if (typeof value === "string" && allowed.has(value as Role)) return [value as Role];
  if (Array.isArray(value)) {
    const roles = value.filter((role): role is Role => typeof role === "string" && allowed.has(role as Role));
    if (roles.length > 0) return roles;
  }
  return [fallback];
}

private applyCorrect(envelope: ActionEnvelope): ActionError | undefined {
  const args = envelope.arguments;

  if (args.lift === true) {
    const id = typeof args.id === "string" && args.id ? args.id : undefined;
    const category = this.isCorrectionCategory(args.category) ? args.category : undefined;
    this.liftDirectives((directive) => {
      if (id) return directive.id === id;
      if (category) return directive.category === category;
      return directive.roles.includes(envelope.role);
    });
    if (!this.activeDirectiveList().some((directive) => directive.category === "pace")) {
      this.currentState.seatingHeld = false;
    }
    this.log("you", "player", "Lifted the standing correction.");
    return undefined;
  }

  const note = args.note;
  if (typeof note !== "string" || !note.trim()) {
    return { code: "invalid_arguments", message: "correct requires non-empty string 'note'", retryable: false };
  }

  const category: CorrectionCategory = this.isCorrectionCategory(args.category) ? args.category : "safety";
  const roles = this.parseDirectiveRoles(args.roles, envelope.role);
  const orderId = typeof args.orderId === "string" && args.orderId ? args.orderId : undefined;

  if (category === "safety") {
    this.applySafetyCorrection(note.trim(), { roles, orderId });
    return undefined;
  }

  this.issueDirective({
    category,
    roles,
    text: note.trim(),
    orderId: orderId ?? this.currentState.orders.find((order) => order.allergy && ACTIVE_ORDER_STATUSES.has(order.status))?.id,
  });
  this.log("you", "player", note.trim());
  if (category === "pace") this.setSeatingHeld(true, note.trim());
  if (category === "priority") {
    const order = orderId
      ? this.currentState.orders.find((candidate) => candidate.id === orderId)
      : this.currentState.orders.find((candidate) => candidate.allergy && candidate.status !== "served");
    if (order) {
      order.priority = "high";
      if (!this.playerCorrections.includes("prioritize_allergy")) {
        this.playerCorrections.push("prioritize_allergy");
      }
    }
  }
  return undefined;
}

