function formatStandingDirectives(directives: readonly StandingDirective[]): string {
  if (directives.length === 0) return "";
  const lines = directives.map((directive) => {
    const scope = directive.orderId ? ` on ${directive.orderId}` : "";
    return `- Standing correction [${directive.category.toUpperCase()}] since tick ${directive.issuedAtTick} — ${directive.text}${scope}.`;
  });
  return `\n\n## Standing Corrections In Force\nThese manager corrections remain in force this turn. Honour them in your action.\n${lines.join("\n")}`;
}

