import { describe, expect, it } from "bun:test";
import { RestaurantGame } from "./restaurant-game.js";
import type { ActionEnvelope, Role, Tool } from "./types.js";

let requestSeq = 0;

function workerEnvelope(
  game: RestaurantGame,
  role: Role,
  tool: Tool,
  args: Record<string, unknown>,
  extra: Partial<ActionEnvelope> = {},
): ActionEnvelope {
  requestSeq += 1;
  const requestId = extra.requestId ?? `req-corr-${requestSeq}`;
  return {
    version: "restaurant-arena-action/v1",
    episodeId: game.state().episode.id,
    actorId: extra.actorId ?? `worker-${role}`,
    actorType: extra.actorType ?? "worker",
    role,
    tool,
    arguments: args,
    tick: extra.tick ?? game.state().episode.tick,
    timestamp: extra.timestamp ?? "2026-09-10T00:00:00Z",
    requestId,
    idempotencyKey: extra.idempotencyKey ?? `${game.state().episode.id}:${requestId}`,
  };
}

function playerEnvelope(
  game: RestaurantGame,
  role: Role,
  tool: Tool,
  args: Record<string, unknown>,
): ActionEnvelope {
  return workerEnvelope(game, role, tool, args, { actorId: "player", actorType: "player" });
}

describe("standing mid-shift corrections", () => {
  it("keeps targeting issued roles on later turns until the correction is lifted", () => {
    const game = new RestaurantGame(218220);
    game.setExternalControllers(["host", "supply_lead", "chef", "server"]);

    expect(game.activeDirectives()).toEqual([]);
    expect(game.directivesFor("chef")).toEqual([]);

    game.step("verify_substitution");
    const afterIssue = game.directivesFor("chef");
    expect(afterIssue).toHaveLength(1);
    expect(afterIssue[0]).toMatchObject({
