import type { ActionEnvelope, Role, Tool } from "./types.js";

it("hands the same standing correction to a role on later orchestrator turns", async () => {
  const game = new RestaurantGame(218220);
  const seen: ActionContext[] = [];
  const orchestrator = new WorkerOrchestrator(game, {
    client: {
      act: async (context) => {
        seen.push(context);
        return workerEnvelope(game, context.role, "inspect", {
          targetId: context.role === "chef" ? "oven-1" : "pass",
        });
      },
    },
  });

  orchestrator.intervene(() => game.step("verify_substitution"));
  orchestrator.resume();
  await orchestrator.runTick();
  await orchestrator.runTick();

  const chefTurns = seen.filter((context) => context.role === "chef");
  expect(chefTurns.length).toBeGreaterThanOrEqual(2);
  expect(chefTurns.every((context) => context.directives?.some((directive) => directive.category === "safety"))).toBe(true);
  expect(seen.filter((context) => context.role === "host").every((context) => (context.directives?.length ?? 0) === 0)).toBe(true);
});

